insert into public.articles (id, slug, status, published_at, is_placeholder, seo_title, seo_description, title, subtitle, excerpt, body, category, tags, cover_path, cover_alt, reading_minutes) values
  ('b0000000-0000-4000-8000-000000000001', 'on-paying-attention', 'published', '2026-10-11T00:00:00.000Z', true, null, null, 'On paying attention', 'A sample essay about noticing, and about leaving things out', 'There is a particular kind of attention that only arrives when nothing is asking for it.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is sample text, written to show how a longer essay sits on the page. Replace it with your own writing from the dashboard."}]},{"type":"paragraph","content":[{"type":"text","text":"There is a particular kind of attention that only arrives when nothing is asking for it. A street you have walked a hundred times turns out to have a bakery with a blue door. The light on a tram window does something it has always done, and you notice it for the first time. None of this is new. What is new is that you were there to see it."}]},{"type":"paragraph","content":[{"type":"text","text":"Writing, at its best, is a way of keeping that attention. It slows a moment down long enough to look at it from more than one side. A sentence is a small frame, the way a photograph is a small frame: it decides what is in and what is left out, and that decision is most of the work."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"On leaving things out"}]},{"type":"paragraph","content":[{"type":"text","text":"The hardest part of any draft is not the adding. It is the cutting. Every paragraph wants to explain itself, and most of them should not be allowed to. "},{"type":"text","text":"Trust the reader","marks":[{"type":"italic"}]},{"type":"text","text":" is advice that sounds generous and feels, in practice, like stepping off a ledge."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"A pull quote or a borrowed line can sit here, set apart from the text around it."}]}]},{"type":"paragraph","content":[{"type":"text","text":"So this space is for the things worth keeping: essays that take their time, short pieces that do not, and the occasional poem that refuses to be anything else."}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","text":"Sample essay. Replace or delete it in the dashboard under Writing.","marks":[{"type":"italic"}]}]}]}'::jsonb, 'Essay', array['sample', 'attention', 'writing'], '/sample/frame-06.jpg', 'Abstract placeholder frame in pale stone tones', 1),
  ('b0000000-0000-4000-8000-000000000002', 'sample-poem', 'published', '2026-10-06T00:00:00.000Z', true, null, null, 'Sample poem', null, 'Line breaks are kept exactly as you type them.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sample poem, first stanza,"},{"type":"hardBreak"},{"type":"text","text":"a line that turns at the end"},{"type":"hardBreak"},{"type":"text","text":"and lands somewhere quieter."}]},{"type":"paragraph","content":[{"type":"text","text":"Line breaks are kept exactly"},{"type":"hardBreak"},{"type":"text","text":"as you type them,"},{"type":"hardBreak"},{"type":"text","text":"with space between stanzas."}]},{"type":"paragraph","content":[{"type":"text","text":"Placeholder. Replace with your own poem.","marks":[{"type":"italic"}]}]}]}'::jsonb, 'Poetry', array['sample'], null, null, 1),
  ('b0000000-0000-4000-8000-000000000003', 'a-sample-observation', 'published', '2026-10-01T00:00:00.000Z', true, null, null, 'A sample observation', 'Short pieces get the same careful layout', 'Shorter pieces work here too: a page or two about a habit of a city.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sample observation. Shorter pieces work here too: a page or two about a conversation overheard, a habit of a city, a thing that keeps happening on the way home."}]},{"type":"paragraph","content":[{"type":"text","text":"The layout stays the same as for a long essay, so nothing feels like a lesser format. Reading time is worked out from the text automatically."}]}]}'::jsonb, 'Observation', array['sample', 'city'], '/sample/frame-07.jpg', 'Abstract placeholder frame in blue-grey tones', 1),
  ('b0000000-0000-4000-8000-000000000004', 'the-last-train', 'published', '2026-09-25T00:00:00.000Z', true, null, null, 'The last train', 'Sample short story', 'The last train had already gone when she reached the platform.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sample short story opening. Fiction is labelled by its category so no one mistakes it for a diary entry."}]},{"type":"paragraph","content":[{"type":"text","text":"The last train had already gone when she reached the platform, and the departure board kept showing it anyway, as if out of politeness. She sat on the bench under it and read the list of stations twice, the way you reread a letter from someone who has moved away."}]},{"type":"paragraph","content":[{"type":"text","text":"Placeholder. Replace with your own story.","marks":[{"type":"italic"}]}]}]}'::jsonb, 'Short story', array['sample', 'fiction'], null, null, 1)
